arguments.command:
cd /tmp && python3 - <<'EOF'
import re
def txt(p):
    x=open(p,encoding='utf-8').read()
    return re.findall(r'<w:t[^>]*>(.*?)</w:t>', x, re.S)
a=txt('/tmp/docx_probe/word/document.xml')
b=txt('/tmp/probe2/word/document.xml')
print('orig paras',len(a),'new paras',len(b))
print(''.join(a)==''.join(b), len(''.join(a)), len(''.join(b)))
if ''.join(a)!=''.join(b):
    import difflib
    for l in list(difflib.unified_diff(a,b,lineterm=''))[:20]: print(l[:200])
EOF

